import{_ as t,o as e,c as a,ae as o}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-05-09","description":"","frontmatter":{"date":"2026-05-09T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-05-09-uxtrend.md","filePath":"daily/2026-05-09-uxtrend.md"}'),n={name:"daily/2026-05-09-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-05-09" tabindex="-1">设计趋势 - 2026-05-09 <a class="header-anchor" href="#设计趋势-2026-05-09" aria-label="Permalink to &quot;设计趋势 - 2026-05-09&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域主要关注AI在用户体验设计中的应用和优化。关键动态包括代理性用户体验设计指南的发布，强调理解用户目标的重要性；AI工作流程的自然交互和目标导向性；以及AI工作流程优化的实用技巧。最值得关注的是AI代理工作流设计模式的探讨，以及设计师角色转变对企业财务的影响。</p><hr><h3 id="_1-为代理性用户体验设计指南" tabindex="-1">1. 为代理性用户体验设计指南 <a class="header-anchor" href="#_1-为代理性用户体验设计指南" aria-label="Permalink to &quot;1. 为代理性用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide | by Kshitij Agrawal - Medium</a></p><p><strong>一句话摘要</strong>: 设计代理性用户体验时，理解用户目标和偏好是关键。</p><p><strong>能解决什么问题</strong>: 解决如何使智能代理更好地理解和执行用户目标的问题。</p><p><strong>产品应用</strong>: 可以应用到智能助手和自动化服务中，通过优化用户交互提升体验。</p><p><strong>示例场景</strong>: 智能助手根据用户偏好自动调整家居设备设置。</p><hr><h3 id="_2-光标、氛围编码和manus-ai所需的用户体验革命" tabindex="-1">2. 光标、氛围编码和Manus：AI所需的用户体验革命 <a class="header-anchor" href="#_2-光标、氛围编码和manus-ai所需的用户体验革命" aria-label="Permalink to &quot;2. 光标、氛围编码和Manus：AI所需的用户体验革命&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/cursor-vibe-coding-and-manus-the-ux-revolution-that-ai-needs-3d3a0f8ccdfa" target="_blank" rel="noreferrer">Cursor, “vibe coding,” and Manus: the UX revolution that AI needs</a></p><p><strong>一句话摘要</strong>: AI直接嵌入工作流程，实现更自然、目标导向的交互。</p><p><strong>能解决什么问题</strong>: 提高工作效率，减少技术障碍，提升用户体验。</p><p><strong>产品应用</strong>: 可应用于软件开发、设计等领域，通过自然交互提升工作效率。</p><p><strong>示例场景</strong>: 设计师使用Manus进行更直观的3D建模。</p><hr><h3 id="_3-ai工作流程优化-7个实用技巧" tabindex="-1">3. AI工作流程优化：7个实用技巧 <a class="header-anchor" href="#_3-ai工作流程优化-7个实用技巧" aria-label="Permalink to &quot;3. AI工作流程优化：7个实用技巧&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@vicki-larson/ai-workflow-optimization-7-game-changing-tips-that-actually-work-414862126f5f" target="_blank" rel="noreferrer">AI Workflow Optimization: 7 Game-Changing Tips That Actually Work</a></p><p><strong>一句话摘要</strong>: 通过创建自定义AI提示和工具，优化设计工作流程。</p><p><strong>能解决什么问题</strong>: 提高设计工作效率，减少重复性任务。</p><p><strong>产品应用</strong>: 适用于需要自动化和优化设计流程的产品团队。</p><p><strong>示例场景</strong>: 设计师使用AI工具生成布局结构和颜色方案。</p><hr><h3 id="_4-ai代理工作流设计模式概览" tabindex="-1">4. AI代理工作流设计模式概览 <a class="header-anchor" href="#_4-ai代理工作流设计模式概览" aria-label="Permalink to &quot;4. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨基于LLM的AI代理工作流设计模式，包括ReAct和Plan-Solve模式。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以通过工具和任务执行解决复杂问题。</p><p><strong>产品应用</strong>: 可应用于开发智能助手，通过灵活工作流解决不同问题。</p><p><strong>示例场景</strong>: 智能助手根据用户指令制作一杯拿铁咖啡。</p><hr><h3 id="_5-设计师作为协调者-不确定的ai-使用cursor设计-ux如何影响损益表" tabindex="-1">5. 设计师作为协调者，不确定的AI，使用Cursor设计，UX如何影响损益表 <a class="header-anchor" href="#_5-设计师作为协调者-不确定的ai-使用cursor设计-ux如何影响损益表" aria-label="Permalink to &quot;5. 设计师作为协调者，不确定的AI，使用Cursor设计，UX如何影响损益表&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/designers-as-orchestrators-uncertain-ai-designing-with-cursor-how-ux-impacts-p-l-557ef6c89e62" target="_blank" rel="noreferrer">Designers as orchestrators, uncertain AI, designing with Cursor, how UX impacts P&amp;L | by Fabricio Teixeira | UX Collective</a></p><p><strong>一句话摘要</strong>: 探讨设计师角色转变、AI的不确定性、设计工具的使用以及UX对企业财务的影响。</p><p><strong>能解决什么问题</strong>: 解决设计师如何适应AI技术发展，提升工作效率和产品用户体验的问题。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI工具辅助设计，优化用户体验，提高企业收益。</p><p><strong>示例场景</strong>: 使用AI辅助设计工具Cursor，提升网页设计的效率和质量。</p><hr><h3 id="_6-提示设计-最佳实践" tabindex="-1">6. 提示设计：最佳实践 <a class="header-anchor" href="#_6-提示设计-最佳实践" aria-label="Permalink to &quot;6. 提示设计：最佳实践&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@mohammednavazpv01/prompt-design-best-practices-6e6538dc99ee" target="_blank" rel="noreferrer">Prompt Design : Best Practices</a></p><p><strong>一句话摘要</strong>: 探索设计提示的最佳实践，提升AI模型交互效率。</p><p><strong>能解决什么问题</strong>: 解决AI模型交互中的模糊性、不确定性和输出意外问题。</p><p><strong>产品应用</strong>: 适用于提高AI驱动应用的直观性和可靠性。</p><p><strong>示例场景</strong>: 使用Google Gemini模型设计更精准的AI交互提示。</p><hr><h3 id="_7-ux设计师指南-如何通过提示让人类与机器相互理解" tabindex="-1">7. UX设计师指南：如何通过提示让人类与机器相互理解 <a class="header-anchor" href="#_7-ux设计师指南-如何通过提示让人类与机器相互理解" aria-label="Permalink to &quot;7. UX设计师指南：如何通过提示让人类与机器相互理解&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/a-ux-designer-guide-to-prompt-f045cd839489" target="_blank" rel="noreferrer">A UX designer guide to prompt. How humans and machines can understand… | by Paz Perez | UX Collective</a></p><p><strong>一句话摘要</strong>: UX实践者通过构建提示来帮助AI模型理解人类请求。</p><p><strong>能解决什么问题</strong>: 解决人类与AI模型之间理解和沟通的障碍。</p><p><strong>产品应用</strong>: 可以应用于AI模型交互界面，如聊天机器人，通过提示改善用户体验。</p><p><strong>示例场景</strong>: 聊天机器人使用提示芯片自动提供上下文相关的回复。</p><hr><h3 id="_8-如何使用chatgpt新图像生成器创建ui" tabindex="-1">8. 如何使用ChatGPT新图像生成器创建UI <a class="header-anchor" href="#_8-如何使用chatgpt新图像生成器创建ui" aria-label="Permalink to &quot;8. 如何使用ChatGPT新图像生成器创建UI&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/how-i-created-ui-with-chatgpts-new-image-generator-4o-d52389a5833e" target="_blank" rel="noreferrer">How I created UI with ChatGPT’s new image generator (4o)</a></p><p><strong>一句话摘要</strong>: 使用ChatGPT的图像生成器创建UI并优化</p><p><strong>能解决什么问题</strong>: 解决UI设计中快速生成视觉原型的问题</p><p><strong>产品应用</strong>: 可应用于产品原型设计，通过AI生成设计选项</p><p><strong>示例场景</strong>: 设计师使用ChatGPT快速生成网页界面原型</p><hr><h3 id="_9-顶尖公司如何将ai应用于设计工作流程" tabindex="-1">9. 顶尖公司如何将AI应用于设计工作流程 <a class="header-anchor" href="#_9-顶尖公司如何将ai应用于设计工作流程" aria-label="Permalink to &quot;9. 顶尖公司如何将AI应用于设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/how-top-companies-are-using-ai-in-their-design-workflows-d10ec40fb6af" target="_blank" rel="noreferrer">How top companies are using AI in their design workflows | by Punit Chawla | UX Collective</a></p><p><strong>一句话摘要</strong>: 顶尖公司通过AI优化设计工作流程，提高效率。</p><p><strong>能解决什么问题</strong>: 解决设计和测试过程中的效率和规模问题。</p><p><strong>产品应用</strong>: 可应用于产品设计，通过AI模板策略加速设计到原型的流程。</p><p><strong>示例场景</strong>: Atlassian利用AI设计工具为大型企业快速构建软件。</p><hr><h3 id="_10-设计提示而非仅仅文字-将流程转化为提示" tabindex="-1">10. 设计提示而非仅仅文字：将流程转化为提示 <a class="header-anchor" href="#_10-设计提示而非仅仅文字-将流程转化为提示" aria-label="Permalink to &quot;10. 设计提示而非仅仅文字：将流程转化为提示&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/design-the-prompt-not-just-the-words-turning-flows-into-prompts-d2c53dc0a38e" target="_blank" rel="noreferrer">Design the prompt, not just the words: turning flows into prompts</a></p><p><strong>一句话摘要</strong>: 将用户流程转化为明确的提示，提高设计可理解性和迭代效率。</p><p><strong>能解决什么问题</strong>: 传统流程设计难以理解和迭代，缺乏明确的步骤和状态管理。</p><p><strong>产品应用</strong>: 适用于需要清晰用户流程和状态管理的产品设计，如电商结账流程。</p><p><strong>示例场景</strong>: 电商平台使用流程提示优化用户结账体验。</p><hr>',75)])])}const u=t(n,[["render",s]]);export{c as __pageData,u as default};
